# CSV側：記録されているHe原子31を選択する
prior_atom_index = 31

lag_frames = 50
time_step_ps = 0.01
dump_stride = 1
dt_frame_ps = time_step_ps * dump_stride

bins = 80
x_limits = (-10.0, 10.0)  # Display limits only; None displays the full range.
chunksize = 100_000

output_png = Path("20261019_MD_vs_current_prior_atom31_xyz_hist_finetune.png")
