def read_md_displacements(path, target_species, lag):
    """
    Select all atoms with target_species in the first frame.

    Use already-unwrapped coordinates.
    No PBC correction is applied here.

    Return:
        values: (number_of_time_origins * number_of_selected_atoms, 3)
        n_frames: number of XYZ frames
        atom_indices: selected zero-based atom indices
    """
    if not path.is_file():
        raise FileNotFoundError(f"MD XYZ not found: {path}")

    if lag < 1:
        raise ValueError("lag must be >= 1")

    buffer = deque(maxlen=lag + 1)
    displacements = []

    reference_species = None
    atom_indices = None
    n_frames = 0

    for species, positions in iter_xyz_frames(path):
        if reference_species is None:
            reference_species = species.copy()

            # Select target atoms once, using the first frame.
            atom_indices = [
                i for i, symbol in enumerate(species)
                if symbol == target_species
            ]

            if not atom_indices:
                raise ValueError(
                    f"No atoms labeled {target_species!r} found in {path}"
                )

            print(
                f"[MD selection] species={target_species}, "
                f"atom_indices={atom_indices}, "
                f"n_atoms={len(atom_indices)}"
            )

        elif species != reference_species:
            raise ValueError(
                f"Atom count/species ordering changed across frames in {path}"
            )

        # Shape: (number_of_selected_atoms, 3)
        coordinates = positions[atom_indices].copy()

        if not np.isfinite(coordinates).all():
            raise ValueError(
                f"Non-finite MD coordinate at frame {n_frames}, "
                f"selected atoms={atom_indices}"
            )

        buffer.append(coordinates)
        n_frames += 1

        if len(buffer) == lag + 1:
            # Keep each atom's displacement as a separate sample.
            displacements.append(buffer[-1] - buffer[0])

    if not displacements:
        raise ValueError(
            f"No MD displacement samples: "
            f"frames={n_frames}, lag_frames={lag}"
        )

    # (time_origins, selected_atoms, 3)
    # -> (time_origins * selected_atoms, 3)
    values = np.asarray(displacements, dtype=float).reshape(-1, 3)

    if not np.isfinite(values).all():
        raise ValueError(
            "MD displacement samples contain NaN or infinity"
        )

    return values, n_frames, atom_indices


def read_prior_samples(paths, atom_index, chunk_size):
    """Read only atom_index and prior components; final components are unused."""
    required = ["atom_index", "prior_dx", "prior_dy", "prior_dz"]
    parts = []
    seen_paths = set()
    for path in paths:
        path = Path(path)
        resolved = path.resolve()
        if resolved in seen_paths:
            raise ValueError(f"The same CSV was specified more than once: {path}")
        seen_paths.add(resolved)
        if not path.is_file():
            raise FileNotFoundError(f"Prior CSV not found: {path}")
        columns = pd.read_csv(path, nrows=0).columns.tolist()
        missing = set(required) - set(columns)
        if missing:
            raise ValueError(
                f"Missing columns in {path}: {sorted(missing)}. "
                "Use the extracted prior-vs-final CSV, not the raw flow-trace CSV."
            )
        n_read = 0
        n_selected = 0
        for chunk in pd.read_csv(path, usecols=required, chunksize=chunk_size):
            n_read += len(chunk)
            selected = chunk.loc[
                chunk["atom_index"].eq(atom_index),
                ["prior_dx", "prior_dy", "prior_dz"],
            ]
            if not selected.empty:
                values = selected.to_numpy(dtype=float)
                if not np.isfinite(values).all():
                    raise ValueError(f"Prior samples contain NaN or infinity in {path}")
                parts.append(values)
                n_selected += len(values)
        print(f"[CSV] {path}: rows={n_read:,}, atom {atom_index} samples={n_selected:,}")
        if n_selected == 0:
            print(f"Warning: no rows for atom {atom_index} in this CSV.")
    if not parts:
        raise ValueError(f"No prior samples for atom_index={atom_index}")
    return np.concatenate(parts, axis=0)


def print_summary(label, vectors):
    means = np.mean(vectors, axis=0)
    stds = np.std(vectors, axis=0, ddof=0)
    rms = np.sqrt(np.mean(vectors ** 2, axis=0))
    print(f"\n[{label}] vector samples={len(vectors):,}; samples per axis={len(vectors):,}")
    for i, axis in enumerate("xyz"):
        print(f"  {axis}: mean={means[i]:.6f} Å, std={stds[i]:.6f} Å, RMS={rms[i]:.6f} Å")


def plot_histograms(md_vectors, prior_vectors, lag_ps):
    # Fixed display limits never truncate the data used for normalization.
    observed_limit = float(max(np.max(np.abs(md_vectors)), np.max(np.abs(prior_vectors))))
    if x_limits is not None:
        observed_limit = max(observed_limit, abs(x_limits[0]), abs(x_limits[1]))
    if observed_limit == 0:
        observed_limit = 1.0
    limit = float(np.nextafter(observed_limit, np.inf))
    edges = np.linspace(-limit, limit, bins + 1)

    fig, axes = plt.subplots(1, 3, figsize=(18.0, 5.2), sharex=True, sharey=True)
    for i, axis in enumerate("xyz"):
        ax = axes[i]
        ax.hist(md_vectors[:, i], bins=edges, density=True,
                color=md_color, alpha=0.68, label=md_label)
        ax.hist(prior_vectors[:, i], bins=edges, density=True,
                color=prior_color, alpha=0.65, label=prior_label)
        ax.set_title(f"Component: Δ{axis}", fontsize=18)
        ax.set_xlabel(f"Δ{axis} (Å)", fontsize=16)
        ax.tick_params(labelsize=12)
        ax.grid(True, ls="--", alpha=0.35)
        ax.set_axisbelow(True)
        # ax.legend(loc="upper right", fontsize=12)
        if x_limits is not None:
            ax.set_xlim(*x_limits)
    axes[0].set_ylabel("Probability density", fontsize=16)
    # fig.suptitle(
    #     f"Atom {target_atom_index}: MD displacement ({lag_ps:g} ps) vs initial prior noise\n"
    #     f"Samples per axis: MD={len(md_vectors):,}, prior={len(prior_vectors):,}",
    #     fontsize=13,
    # )
    fig.suptitle(
        f"{md_target_species}: MD displacement ({lag_ps:g} ps) "
        f"vs initial prior noise\n"
        f"MD: all {md_target_species} atoms; "
        f"prior: CSV atom {prior_atom_index}; "
        f"samples per axis: MD={len(md_vectors):,}, "
        f"prior={len(prior_vectors):,}",
        fontsize=13,
    )
    # fig.tight_layout(rect=(0, 0, 1, 0.88))
    # fig.tight_layout(pad=1.0)
    # 最初のパネルから、2種類の凡例情報を取得する
    handles, labels = axes[0].get_legend_handles_labels()

    # 図全体で共通の凡例を、下側に横並びで表示する
    fig.legend(
        handles,
        labels,
        loc="lower center",
        bbox_to_anchor=(0.5, 0.01),
        ncol=2,
        fontsize=12,
        frameon=False,
    )

    # 下側の約9%を凡例用に空ける
    fig.tight_layout(
        rect=(0, 0.09, 1, 1),
        pad=1.0,
    )
    
    output_png.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(output_png, dpi=180, bbox_inches="tight")
    plt.close(fig)
    print(f"\nSaved: {output_png}")
    if x_limits is not None:
        lo, hi = x_limits
        if ((md_vectors < lo) | (md_vectors > hi)).any() or ((prior_vectors < lo) | (prior_vectors > hi)).any():
            print("Note: some samples lie outside the display limits; all samples were used for normalization.")


