def main():
    if not prior_csv_paths:
        raise ValueError("prior_csv_paths is empty")

    if bins < 1 or chunksize < 1 or dt_frame_ps <= 0:
        raise ValueError(
            "bins, chunksize and dt_frame_ps must be positive"
        )

    if x_limits is not None and (
        len(x_limits) != 2 or x_limits[0] >= x_limits[1]
    ):
        raise ValueError(
            "x_limits must be None or an increasing pair"
        )

    # MD: select every atom labeled He.
    md_vectors, n_frames, md_atom_indices = read_md_displacements(
        md_xyz_path,
        md_target_species,
        lag_frames,
    )

    # CSV: select atom_index == 31.
    prior_vectors = read_prior_samples(
        prior_csv_paths,
        prior_atom_index,
        chunksize,
    )

    lag_ps = lag_frames * dt_frame_ps
    n_time_origins = n_frames - lag_frames

    print(
        f"\n[MD] {md_xyz_path}: "
        f"frames={n_frames:,}, "
        f"species={md_target_species}, "
        f"atom_indices={md_atom_indices}"
    )

    print(
        f"[MD samples] "
        f"{n_time_origins:,} time origins "
        f"× {len(md_atom_indices)} atoms "
        f"= {len(md_vectors):,} displacement vectors"
    )

    print(
        f"[Prior selection] CSV atom_index={prior_atom_index}"
    )

    print(
        f"[Lag] {lag_frames} frames "
        f"× {dt_frame_ps:g} ps/frame "
        f"= {lag_ps:g} ps"
    )

    print_summary(md_label, md_vectors)
    print_summary(prior_label, prior_vectors)

    if len(prior_vectors) < 100:
        print(
            "\nNote: few prior samples; histogram shape may be noisy. "
            "More seeds/steps can be combined."
        )

    plot_histograms(md_vectors, prior_vectors, lag_ps)


if __name__ == "__main__":
    main()


